#pragma once
#include <vector>
#include <cstddef>
#include <limits>

// Metrics over a volume time-series (storage or production).
// All functions take a plain vector of doubles; NaN values are propagated.

namespace oil_volume {

// Capacity utilization % = value / capacity_kb * 100.
// capacity_kb is the Cushing operational capacity in thousand barrels
// (current DOE figure: ~76,000 kb; can be overridden by caller).
std::vector<double> capacity_utilization(
    const std::vector<double>& storage_kb,
    double capacity_kb);

// Days of supply = storage_kb / (production_kbd / 7.0)
// production_kbd = production in thousand barrels per day.
// Returns NaN where production_kbd <= 0.
std::vector<double> days_of_supply(
    const std::vector<double>& storage_kb,
    const std::vector<double>& production_kbd);

// Fill rate = week-over-week change in storage (storage[i] - storage[i-1]).
// First element is NaN (no prior period).
std::vector<double> fill_rate(const std::vector<double>& storage_kb);

// Rolling mean (same as the bridge function, exposed for use by volume_metrics).
std::vector<double> rolling_mean(const std::vector<double>& values, int window);

}  // namespace oil_volume

