#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

#include <stdexcept>
#include <vector>

namespace py = pybind11;

// Simple rolling mean over a flat array.  Returns a vector of the same length;
// the first (window-1) positions are NaN (not enough data yet).
std::vector<double> rolling_mean(const std::vector<double>& values, int window) {
    if (window <= 0) throw std::invalid_argument("window must be positive");
    const std::size_t n = values.size();
    std::vector<double> out(n, std::numeric_limits<double>::quiet_NaN());
    double sum = 0.0;
    for (std::size_t i = 0; i < n; ++i) {
        sum += values[i];
        if (i >= static_cast<std::size_t>(window)) sum -= values[i - window];
        if (i + 1 >= static_cast<std::size_t>(window)) {
            out[i] = sum / window;
        }
    }
    return out;
}

PYBIND11_MODULE(oil_volume_cpp, m) {
    m.doc() = "C++ core for oil-volume metrics (pybind11 bridge)";
    m.def(
        "rolling_mean",
        &rolling_mean,
        py::arg("values"),
        py::arg("window"),
        "Compute a rolling arithmetic mean over *values* with the given *window*.\n"
        "Returns a list of length len(values); the first window-1 entries are NaN."
    );
}

