"""Wrapper for the oil-volume C++ extension with a pure-Python fallback.

Importing this module never fails. If ``oil_volume_cpp`` is not built the
pure-Python implementations are used instead and ``USING_CPP`` is False.
Callers can display a "running unoptimised" notice when ``USING_CPP`` is
False.
"""

from __future__ import annotations

import math
from typing import Sequence

try:
    import oil_volume_cpp as _cpp

    USING_CPP = True
except ImportError:
    _cpp = None  # type: ignore[assignment]
    USING_CPP = False

# Cushing, OK operational storage capacity (thousand barrels, DOE figure as of 2024).
CUSHING_CAPACITY_KB: float = 76_000.0


# ─── Public API ───────────────────────────────────────────────────────────────

def capacity_utilization(storage_kb: Sequence[float], capacity_kb: float = CUSHING_CAPACITY_KB) -> list[float]:
    """Capacity utilization % = storage_kb / capacity_kb * 100."""
    if USING_CPP:
        return _cpp.capacity_utilization(list(storage_kb), capacity_kb)
    if capacity_kb <= 0:
        raise ValueError("capacity_kb must be positive")
    return [v / capacity_kb * 100.0 for v in storage_kb]


def days_of_supply(storage_kb: Sequence[float], production_kbd: Sequence[float]) -> list[float]:
    """Days of supply = storage_kb / production_kbd.

    production_kbd is in thousand barrels per day. Returns NaN where production <= 0.
    """
    if USING_CPP:
        return _cpp.days_of_supply(list(storage_kb), list(production_kbd))
    out: list[float] = []
    for s, p in zip(storage_kb, production_kbd):
        out.append(math.nan if (math.isnan(p) or p <= 0) else s / p)
    return out


def fill_rate(storage_kb: Sequence[float]) -> list[float]:
    """Week-over-week change in storage (storage[i] - storage[i-1]).

    First element is NaN (no prior period).
    """
    if USING_CPP:
        return _cpp.fill_rate(list(storage_kb))
    lst = list(storage_kb)
    if not lst:
        return []
    out = [math.nan]
    for i in range(1, len(lst)):
        out.append(lst[i] - lst[i - 1])
    return out


def rolling_mean(values: Sequence[float], window: int) -> list[float]:
    """Rolling arithmetic mean; first (window-1) entries are NaN."""
    if USING_CPP:
        return _cpp.rolling_mean(list(values), window)
    if window <= 0:
        raise ValueError("window must be positive")
    lst = list(values)
    out: list[float] = []
    for i, _ in enumerate(lst):
        if i + 1 < window:
            out.append(math.nan)
        else:
            out.append(sum(lst[i - window + 1 : i + 1]) / window)
    return out

