#include "order_book.hpp"

namespace itch {

void OrderBook::add(uint64_t order_ref, char side, uint32_t price_raw, uint32_t shares) {
    if (orders_.count(order_ref)) {
        // Duplicate add — ignore and count as error.
        ++error_count_;
        return;
    }
    orders_[order_ref] = {side, price_raw, shares};
    auto& level_map = (side == 'B') ? bids_ : asks_;
    level_map[price_raw] += shares;
}

uint32_t OrderBook::execute(uint64_t order_ref, uint32_t executed_shares) {
    auto it = orders_.find(order_ref);
    if (it == orders_.end()) {
        ++error_count_;
        return 0;
    }
    OrderRecord& rec = it->second;
    uint32_t to_remove = std::min(executed_shares, rec.shares);
    _remove_shares(rec.side, rec.price_raw, to_remove);
    rec.shares -= to_remove;
    if (rec.shares == 0) {
        orders_.erase(it);
    }
    return to_remove;
}

bool OrderBook::del(uint64_t order_ref) {
    auto it = orders_.find(order_ref);
    if (it == orders_.end()) {
        ++error_count_;
        return false;
    }
    const OrderRecord& rec = it->second;
    _remove_shares(rec.side, rec.price_raw, rec.shares);
    orders_.erase(it);
    return true;
}

void OrderBook::replace(uint64_t old_ref, uint64_t new_ref,
                        uint32_t shares, uint32_t price_raw) {
    auto it = orders_.find(old_ref);
    if (it == orders_.end()) {
        ++error_count_;
        return;
    }
    const char side = it->second.side;
    // Remove old order from price levels.
    _remove_shares(side, it->second.price_raw, it->second.shares);
    orders_.erase(it);
    // Add the replacement.
    add(new_ref, side, price_raw, shares);
}

TopOfBook OrderBook::top_of_book() const {
    TopOfBook tob;
    if (!bids_.empty()) {
        const auto& [price, shares] = *bids_.begin();
        tob.best_bid = PriceLevel{price, shares};
    }
    if (!asks_.empty()) {
        const auto& [price, shares] = *asks_.begin();
        tob.best_ask = PriceLevel{price, shares};
    }
    return tob;
}

void OrderBook::_remove_shares(char side, uint32_t price_raw, uint32_t shares) {
    auto& level_map = (side == 'B') ? bids_ : asks_;
    auto it = level_map.find(price_raw);
    if (it == level_map.end()) {
        ++error_count_;
        return;
    }
    if (it->second <= shares) {
        level_map.erase(it);
    } else {
        it->second -= shares;
    }
}

}  // namespace itch

