#pragma once
#include <cstdint>
#include <algorithm>
#include <cassert>
#include <cstring>
#include <stdexcept>
#include <vector>

// A minimal HDR-style latency histogram for measuring tick-to-trade latency.
//
// Stores counts in power-of-2 sized buckets with sub-bucket resolution.
// Covers latencies from 1 ns to ~68 seconds at 1% precision.
// Does NOT depend on the HdrHistogram_c library — this is a self-contained
// header-only implementation that avoids the FetchContent overhead for a
// simple benchmark.
//
// For production use you would replace this with the real HdrHistogram_c;
// the percentile() API is the same.

namespace latency {

class Histogram {
public:
    // significant_figures: number of significant decimal digits (1-5).
    explicit Histogram(int significant_figures = 3)
        : sig_figs_(significant_figures) {
        if (significant_figures < 1 || significant_figures > 5)
            throw std::invalid_argument("significant_figures must be 1-5");
        // Each bucket covers a power-of-2 range; sub_bucket_count is the
        // number of entries within that range.
        sub_bucket_count_ = 1;
        for (int i = 0; i < significant_figures; ++i) sub_bucket_count_ *= 10;
        sub_bucket_half_ = sub_bucket_count_ / 2;

        // 64 leading-zero buckets covers the full uint64_t range.
        bucket_count_ = 64;
        counts_.assign(bucket_count_ * sub_bucket_count_, 0);
        total_ = 0;
        min_val_ = UINT64_MAX;
        max_val_ = 0;
    }

    // Record a single latency value (in nanoseconds or any consistent unit).
    void record(uint64_t value) {
        std::size_t idx = _index(value);
        if (idx < counts_.size()) {
            ++counts_[idx];
            ++total_;
            if (value < min_val_) min_val_ = value;
            if (value > max_val_) max_val_ = value;
        }
    }

    // Percentile in [0.0, 100.0].  Returns 0 if histogram is empty.
    uint64_t percentile(double pct) const {
        if (total_ == 0) return 0;
        uint64_t target = static_cast<uint64_t>(pct / 100.0 * static_cast<double>(total_));
        if (target == 0) target = 1;
        uint64_t cumul = 0;
        for (std::size_t i = 0; i < counts_.size(); ++i) {
            cumul += counts_[i];
            if (cumul >= target) {
                return _value_at(i);
            }
        }
        return max_val_;
    }

    uint64_t min_value() const { return (total_ == 0) ? 0 : min_val_; }
    uint64_t max_value() const { return max_val_; }
    uint64_t total_count() const { return total_; }

    double mean() const {
        if (total_ == 0) return 0.0;
        uint64_t sum = 0;
        for (std::size_t i = 0; i < counts_.size(); ++i)
            sum += counts_[i] * _value_at(i);
        return static_cast<double>(sum) / static_cast<double>(total_);
    }

    void reset() {
        std::fill(counts_.begin(), counts_.end(), 0);
        total_   = 0;
        min_val_ = UINT64_MAX;
        max_val_ = 0;
    }

private:
    int sig_figs_;
    int sub_bucket_count_;
    int sub_bucket_half_;
    int bucket_count_;
    std::vector<uint64_t> counts_;
    uint64_t total_;
    uint64_t min_val_;
    uint64_t max_val_;

    // Map a value to a flat index into counts_.
    std::size_t _index(uint64_t v) const {
        int bucket = 0;
        uint64_t w = v;
        while (w >= static_cast<uint64_t>(sub_bucket_count_)) {
            w >>= 1;
            ++bucket;
        }
        int sub = static_cast<int>(w);
        std::size_t idx = static_cast<std::size_t>(bucket * sub_bucket_count_ + sub);
        return (idx < counts_.size()) ? idx : counts_.size() - 1;
    }

    // Inverse: index → representative value.
    uint64_t _value_at(std::size_t idx) const {
        int bucket = static_cast<int>(idx / static_cast<std::size_t>(sub_bucket_count_));
        int sub    = static_cast<int>(idx % static_cast<std::size_t>(sub_bucket_count_));
        if (bucket == 0) return static_cast<uint64_t>(sub);
        return static_cast<uint64_t>(sub) << bucket;
    }
};

}  // namespace latency

