// Tick-to-trade latency benchmark.
// Usage:  bench_main <itch_sample.bin>
//
// Reads a Nasdaq TotalView-ITCH 5.0 sample file (MoldUDP64-framed), rebuilds
// the L2 order book message-by-message, and records the wall-clock latency
// (CLOCK_MONOTONIC) from the start of each message parse to the signal emit.
// Prints p50 / p99 / p99.9 latencies in nanoseconds, and a simple stats line.
//
// When the file path argument is omitted (or the file cannot be opened), the
// binary falls back to a synthetic in-memory message stream so the harness can
// be tested without a real sample file.

#include "itch_parser.hpp"
#include "order_book.hpp"
#include "signal.hpp"
#include "../common/latency_histogram.hpp"

#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <vector>

// ─── Monotonic clock helper ──────────────────────────────────────────────────

static inline uint64_t now_ns() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return static_cast<uint64_t>(ts.tv_sec) * 1'000'000'000ULL
         + static_cast<uint64_t>(ts.tv_nsec);
}

// ─── Synthetic message generator ─────────────────────────────────────────────

static void put_be16(uint8_t* p, uint16_t v) {
    p[0] = (v >> 8) & 0xff; p[1] = v & 0xff;
}
static void put_be32(uint8_t* p, uint32_t v) {
    p[0] = (v >> 24) & 0xff; p[1] = (v >> 16) & 0xff;
    p[2] = (v >>  8) & 0xff; p[3] =  v        & 0xff;
}
static void put_be64(uint8_t* p, uint64_t v) {
    put_be32(p,     static_cast<uint32_t>(v >> 32));
    put_be32(p + 4, static_cast<uint32_t>(v));
}

static std::vector<uint8_t> build_synthetic_stream(int n_orders) {
    std::vector<uint8_t> buf;
    buf.reserve(static_cast<std::size_t>(n_orders) * (2 + 36));

    for (int i = 0; i < n_orders; ++i) {
        const uint16_t msg_len = 36;
        buf.resize(buf.size() + 2 + msg_len, 0);
        uint8_t* p = buf.data() + buf.size() - 2 - msg_len;
        put_be16(p, msg_len);
        p[2] = 'A';
        const uint64_t ref   = static_cast<uint64_t>(i + 1);
        const char     side  = (i % 2 == 0) ? 'B' : 'S';
        const uint32_t price = (side == 'B') ? 1000000u + static_cast<uint32_t>(i % 10) * 100u
                                             : 1010000u + static_cast<uint32_t>(i % 10) * 100u;
        const uint32_t shares = 100u;
        put_be64(p + 2 + 11, ref);
        p[2 + 19] = static_cast<uint8_t>(side);
        put_be32(p + 2 + 20, shares);
        put_be32(p + 2 + 32, price);
    }
    return buf;
}

// ─── Benchmark loop ──────────────────────────────────────────────────────────

static void run_benchmark(const uint8_t* data, std::size_t len) {
    itch::OrderBook book;
    latency::Histogram hist(3);

    itch::MessageVisitor visitor;
    visitor.on_add = [&](const itch::AddOrder& m) {
        const uint64_t t0 = now_ns();
        book.add(m.order_ref, m.side, m.price, m.shares);
        itch::make_signal(book);
        const uint64_t t1 = now_ns();
        hist.record(t1 - t0);
    };
    visitor.on_execute = [&](const itch::ExecuteOrder& m) {
        const uint64_t t0 = now_ns();
        book.execute(m.order_ref, m.executed_shares);
        itch::make_signal(book);
        const uint64_t t1 = now_ns();
        hist.record(t1 - t0);
    };
    visitor.on_delete = [&](const itch::DeleteOrder& m) {
        const uint64_t t0 = now_ns();
        book.del(m.order_ref);
        itch::make_signal(book);
        const uint64_t t1 = now_ns();
        hist.record(t1 - t0);
    };
    visitor.on_replace = [&](const itch::ReplaceOrder& m) {
        const uint64_t t0 = now_ns();
        book.replace(m.old_order_ref, m.new_order_ref, m.shares, m.price);
        itch::make_signal(book);
        const uint64_t t1 = now_ns();
        hist.record(t1 - t0);
    };

    const itch::ParseStats stats = itch::parse_buffer(data, len, visitor);

    printf("=== ITCH Bench: tick-to-trade latency ===\n");
    printf("Messages parsed:  add=%llu  execute=%llu  delete=%llu  replace=%llu\n",
           (unsigned long long)stats.add_count,
           (unsigned long long)stats.execute_count,
           (unsigned long long)stats.delete_count,
           (unsigned long long)stats.replace_count);
    printf("Skipped: %llu  Errors: %llu\n",
           (unsigned long long)stats.skipped_count,
           (unsigned long long)stats.error_count);
    printf("Latency (ns):  p50=%llu  p99=%llu  p99.9=%llu  mean=%.1f  max=%llu\n",
           (unsigned long long)hist.percentile(50.0),
           (unsigned long long)hist.percentile(99.0),
           (unsigned long long)hist.percentile(99.9),
           hist.mean(),
           (unsigned long long)hist.max_value());
    printf("Total timed events: %llu\n", (unsigned long long)hist.total_count());
}

// ─── main ────────────────────────────────────────────────────────────────────

int main(int argc, char** argv) {
    std::vector<uint8_t> data;

    if (argc >= 2) {
        std::ifstream f(argv[1], std::ios::binary | std::ios::ate);
        if (!f) {
            fprintf(stderr, "Cannot open '%s' — falling back to synthetic stream.\n", argv[1]);
        } else {
            const std::streamsize sz = f.tellg();
            f.seekg(0);
            data.resize(static_cast<std::size_t>(sz));
            f.read(reinterpret_cast<char*>(data.data()), sz);
            fprintf(stderr, "Loaded %lld bytes from '%s'.\n", (long long)sz, argv[1]);
        }
    }

    if (data.empty()) {
        fprintf(stderr, "Using synthetic stream (100,000 Add Order messages).\n");
        data = build_synthetic_stream(100'000);
    }

    run_benchmark(data.data(), data.size());
    return 0;
}

