    printf("Latency (ns):  p50=%llu  p99=%llu  p99.9=%llu  mean=%.1f  max=%llu\n",
           (unsigned long long)hist.percentile(50.0),
           (unsigned long long)hist.percentile(99.0),
           (unsigned long long)hist.percentile(99.9),
           hist.mean(),
           (unsigned long long)hist.max_value());
    printf("Total timed events: %llu\n", (unsigned long long)hist.total_count());
    return 0;
}

