#pragma once
#include "order_book.hpp"
#include "order_book_flat.hpp"
#include <functional>

// Trivial top-of-book signal emitted each time the book changes.
// Downstream consumers register a callback; the engine calls it after every update.

namespace itch {

struct TopOfBookSignal {
    double bid_price;   // best bid in real price units (raw / 10000.0)
    double ask_price;   // best ask in real price units
    double mid;         // (bid + ask) / 2.0; NaN if one side is empty
    uint32_t bid_shares;
    uint32_t ask_shares;
    bool valid;         // false if either side is empty
};

using SignalCallback = std::function<void(const TopOfBookSignal&)>;

// Compute a TopOfBookSignal from any type that exposes top_of_book().
// Works with both OrderBook and OrderBookFlat.
template<typename Book>
inline TopOfBookSignal make_signal(const Book& book) {
    TopOfBookSignal sig{};
    const TopOfBook tob = book.top_of_book();
    if (tob.best_bid && tob.best_ask) {
        sig.bid_price  = tob.best_bid->price_raw / 10000.0;
        sig.ask_price  = tob.best_ask->price_raw / 10000.0;
        sig.bid_shares = tob.best_bid->shares;
        sig.ask_shares = tob.best_ask->shares;
        sig.mid        = (sig.bid_price + sig.ask_price) / 2.0;
        sig.valid      = true;
    } else if (tob.best_bid) {
        sig.bid_price  = tob.best_bid->price_raw / 10000.0;
        sig.bid_shares = tob.best_bid->shares;
        sig.valid      = false;
    } else if (tob.best_ask) {
        sig.ask_price  = tob.best_ask->price_raw / 10000.0;
        sig.ask_shares = tob.best_ask->shares;
        sig.valid      = false;
    }
    return sig;
}

}  // namespace itch

